        "content": "The complete exploit/solver script (solve.py) is provided below:",
        "code": "#!/usr/bin/env python3\r\n\r\nfrom math import isqrt\r\nfrom Crypto.Util.number import long_to_bytes\r\n\r\nN = \r\n\r\ne = 65537\r\n\r\nc = \r\n\r\nP_BOUND = 1 << 607\r\nQ_BOUND = 1 << 521\r\n\r\n# N = (2^607 - x)(2^521 - y)\r\ndelta = P_BOUND * Q_BOUND - N\r\n\r\n# delta ≡ -xy (mod 2^521)\r\nxy = (-delta) % Q_BOUND\r\n\r\nprint(f\"[+] xy = {xy}\")\r\n\r\np = None\r\nq = None\r\n\r\n# Cari seluruh pasangan faktor xy.\r\nfor divisor in range(1, isqrt(xy) + 1):\r\n    if xy % divisor != 0:\r\n        continue\r\n\r\n    factor_pairs = [\r\n        (divisor, xy // divisor),\r\n        (xy // divisor, divisor),\r\n    ]\r\n\r\n    for x, y in factor_pairs:\r\n        candidate_p = P_BOUND - x\r\n        candidate_q = Q_BOUND - y\r\n\r\n        if candidate_p * candidate_q == N:\r\n            p = candidate_p\r\n            q = candidate_q\r\n\r\n            print(f\"[+] x = {x}\")\r\n            print(f\"[+] y = {y}\")\r\n            break\r\n\r\n    if p is not None:\r\n        break\r\n\r\nif p is None or q is None:\r\n    raise ValueError(\"Faktor N tidak ditemukan\")\r\n\r\nassert p.bit_length() == 607\r\nassert q.bit_length() == 521\r\nassert p * q == N\r\n\r\nphi = (p - 1) * (q - 1)\r\nd = pow(e, -1, phi)\r\n\r\nm = pow(c, d, N)\r\nflag = long_to_bytes(m)\r\n\r\nprint(f\"[+] p = {p}\")\r\nprint(f\"[+] q = {q}\")\r\nprint(f\"[+] flag = {flag.decode()}\")"
